import json,collections,factstore
info=collections.defaultdict(lambda:{'em':set(),'ad':set()})
def nm(e):
    e=e.lower().strip(); l,d=e.split('@'); l=l.split('+')[0]
    if d in('gmail.com','googlemail.com'): l=l.replace('.','')
    return l+'@'+d
for l in open('shopify/orders.jsonl'):
    d=json.loads(l); c=d.get('customer')
    if not c: continue
    x=info[c['id'].split('/')[-1]]
    for e in (c.get('email'),d.get('email')):
        if e: x['em'].add(nm(e))
    a=d.get('shippingAddress') or {}
    if a.get('name'): x['ad'].add((a['name'].lower().strip(),(a.get('address1') or '').lower().strip(),a.get('zip')))
rows=factstore.query('select a.v,b.v from "core/same_as" s join "shopify/customer_id" a on a.e=s.e join "shopify/customer_id" b on b.e=s.v').rows
cnt=collections.Counter();bad=[]
for n,o in rows:
    A,B=info[n],info[o]
    if A['em']&B['em']: r='mailbox'
    elif A['ad']&B['ad']: r='name+address'
    else: r='none'; bad.append((n,o))
    cnt[r]+=1
print(cnt,bad[:10])
E

